def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    ref = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    if not ref:
        return out

    rs = [r for r, c in ref]
    cs = [c for r, c in ref]
    length = len(ref)

    if len(set(rs)) == 1:
        kind, step = "row", (0, -1)
    elif len(set(cs)) == 1:
        kind, step = "col", (-1, 0)
    elif len({r + c for r, c in ref}) == 1:
        kind, step = "sum", (1, -1)
    else:
        kind, step = "diff", (-1, -1)

    def key(r, c):
        if kind == "row":
            return r
        if kind == "col":
            return c
        if kind == "sum":
            return r + c
        return r - c

    colors = set(v for row in grid for v in row) - {7, 8}
    for color in colors:
        groups = {}
        for r in range(h):
            for c in range(w):
                if grid[r][c] == color:
                    groups.setdefault(key(r, c), []).append((r, c))

        for cells in groups.values():
            for r, c in cells:
                out[r][c] = 7
            # Keep the endpoint with the greatest column and extend from it.
            r, c = max(cells, key=lambda p: p[1])
            dr, dc = step
            for i in range(length):
                rr, cc = r + i * dr, c + i * dc
                if 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = color

    return out
